               "image": "https://m.media-amazon.com/images/M/MV5BMjQ2NzYxMDQ2OV5BMl5BanBnXkFtZTgwMDk2MzczOTE@._V1_Ratio0.6763_AL_.jpg",
               "imDbRating": "5.7"
