               "image": "https://m.media-amazon.com/images/M/MV5BMTg3ODk5ODE0NV5BMl5BanBnXkFtZTcwNDkzODM1NA@@._V1_Ratio0.6763_AL_.jpg",
               "imDbRating": "6.9"
