               "image": "https://m.media-amazon.com/images/M/MV5BMTYzNDc2MDc0N15BMl5BanBnXkFtZTgwOTcwMDQ5MTE@._V1_Ratio0.6763_AL_.jpg",
               "imDbRating": "7.9"
